+import { db } from "../src/db";
+import { enqueueEmail } from "../src/email/queue";
+
+// One-off win-back: every customer with no order in the last 365 days gets the spring offer.
+async function main() {
+  const lapsed = await db.query(
+    `SELECT id, email, first_name FROM customers
+     WHERE last_order_at < now() - interval '365 days'`,
+  );
+  console.log(`queueing ${lapsed.rows.length} emails`);
+  for (const c of lapsed.rows) {
+    await enqueueEmail({
+      to: c.email,
+      template: "spring-winback",
+      vars: { firstName: c.first_name, code: "COMEBACK20" },
+      sendAt: new Date(),
+    });
+  }
+}
+
+main();
+
